@app.cell(hide_code=True)
def load_sbom_by_ecosystem(mo, pyoso_db_conn):
    df_sbom_ecosystems = mo.sql(
        f"""
        SELECT
          s.package_artifact_source AS ecosystem,
          COUNT(*) AS total_edges,
          COUNT(DISTINCT s.dependent_artifact_name) AS total_repos,
          COUNT(DISTINCT CASE
            WHEN a.repo IS NOT NULL THEN s.dependent_artifact_name
          END) AS ai_repos
        FROM oso.sboms_v0 s
        LEFT JOIN currentai.catalog.goodailist_repos a
          ON s.dependent_artifact_namespace || '/' || s.dependent_artifact_name = a.repo
        GROUP BY s.package_artifact_source
        ORDER BY total_edges DESC
        """,
        output=False,
        engine=pyoso_db_conn,
    )
    return (df_sbom_ecosystems,)


