    _df = df_foundation.copy()
    _df["transitive_ratio"] = _df["transitive"] / _df["total_dependents"]
    _pillars = _df[
        (_df["transitive_ratio"] > 0.7) & (_df["total_dependents"] >= 50)
    ].sort_values("total_dependents", ascending=True).tail(15)

