@app.cell(hide_code=True)
def load_cross_category(mo, pyoso_db_conn):
    df_cross_cat = mo.sql(
        f"""
        SELECT
          dependent_category,
          dependency_category,
          COUNT(*) AS edge_count
        FROM currentai.scores.dependency_graph
        WHERE min_depth = 1
        GROUP BY dependent_category, dependency_category
        ORDER BY edge_count DESC
        """,
        output=False,
        engine=pyoso_db_conn,
    )
    return (df_cross_cat,)


@app.cell(hide_code=True)
def cross_category_heatmap(C, CHART_LAYOUT, F, df_cross_cat, go, mo):
    _pivot = df_cross_cat.pivot_table(
        index="dependent_category",
        columns="dependency_category",
        values="edge_count",
        fill_value=0,
    )
    _cats = sorted(set(df_cross_cat["dependent_category"]) | set(df_cross_cat["dependency_category"]))
    _pivot = _pivot.reindex(index=_cats, columns=_cats, fill_value=0)

    _fig = go.Figure(go.Heatmap(
        z=_pivot.values,
        x=_pivot.columns.tolist(),
        y=_pivot.index.tolist(),
        colorscale=[
            [0, "white"],
            [0.3, C["paper_2"]],
            [0.6, C["warm"]],
            [1.0, C["accent"]],
        ],
        hovertemplate=(
            "Depends on: %{x}<br>"
            "Depended by: %{y}<br>"
            "Edges: %{z:,}<extra></extra>"
        ),
    ))
    _fig.update_layout(
        **{**CHART_LAYOUT, "height": 420},
        xaxis=dict(title="Dependency (provides)", tickangle=35, tickfont=dict(size=10)),
        yaxis=dict(title="Dependent (consumes)", tickfont=dict(size=10)),
    )

    mo.vstack([
        mo.Html(
            f'<h3 style="font-family:{F["headline"]}; font-size:1.1rem; font-weight:500; '
            f'color:{C["ink"]}; margin:32px 0 4px;">Cross-Category Dependencies</h3>'
            f'<p style="font-family:{F["body"]}; font-size:0.85rem; color:{C["ink_3"]}; '
            f'margin:0 0 12px;">Direct dependency flow between GoodAI categories. '
            f'Rows consume, columns provide. Darker = more dependency edges.</p>'
        ),
        mo.ui.plotly(_fig, config={"displayModeBar": False}),
    ])
    return


