@app.cell(hide_code=True)
def load_explorer_deps(explorer_repo, mo, pyoso_db_conn):
    _selected = explorer_repo.value
    df_explorer = mo.sql(
        f"""
        SELECT
          dependent_repo,
          dependent_category,
          min_depth
        FROM currentai.scores.dependency_graph
        WHERE dependency_repo = '{_selected}'
        ORDER BY min_depth, dependent_repo
        """,
        output=False,
        engine=pyoso_db_conn,
    )
    df_explorer_provides = mo.sql(
        f"""
        SELECT
          dependency_repo,
          dependency_category,
          min_depth
        FROM currentai.scores.dependency_graph
        WHERE dependent_repo = '{_selected}'
        ORDER BY min_depth, dependency_repo
        """,
        output=False,
        engine=pyoso_db_conn,
    )
    return df_explorer, df_explorer_provides


