@app.cell(hide_code=True)
def load_license_data(mo, pyoso_db_conn):
    df_licenses = mo.sql(
        f"""
        SELECT
          r.license,
          COUNT(*) AS repo_count
        FROM currentai.catalog.goodailist_repos r
        WHERE r.license IS NOT NULL AND r.license != ''
        GROUP BY r.license
        ORDER BY repo_count DESC
        LIMIT 20
        """,
        output=False,
        engine=pyoso_db_conn,
    )
    return (df_licenses,)


@app.cell(hide_code=True)
def load_license_coverage(mo, pyoso_db_conn):
    df_license_cov = mo.sql(
        f"""
        SELECT
          COUNT(*) AS total_repos,
          COUNT(CASE WHEN license IS NOT NULL AND license != '' THEN 1 END)
            AS has_license
        FROM currentai.catalog.goodailist_repos
        """,
        output=False,
        engine=pyoso_db_conn,
    )
    return (df_license_cov,)


@app.cell(hide_code=True)
def tier2_license_chart(
    C,
    CHART_LAYOUT,
    F,
    df_license_cov,
    df_licenses,
    go,
    mo,
):
    _total = int(df_license_cov["total_repos"].iloc[0])
    _has = int(df_license_cov["has_license"].iloc[0])

    _df = df_licenses.head(15).sort_values("repo_count", ascending=True)

    _permissive = {"MIT License", "Apache License 2.0", "BSD 3-Clause License",
                   "BSD 2-Clause License", "ISC License", "Unlicense"}
    _colors = [
        C["healthy"] if lic in _permissive else C["warm"]
        for lic in _df["license"]
    ]

    _fig = go.Figure(go.Bar(
        y=_df["license"],
        x=_df["repo_count"],
        orientation="h",
        marker_color=_colors,
        hovertemplate="<b>%{y}</b><br>Repos: %{x:,}<extra></extra>",
    ))
    _fig.update_layout(
        **{**CHART_LAYOUT, "height": max(300, len(_df) * 28)},
        xaxis=dict(title="Repo count", showgrid=True, gridcolor=C["rule"]),
        yaxis=dict(title="", showgrid=False, tickfont=dict(size=10)),
    )

    mo.vstack([
        mo.hstack([
            mo.stat(
                label="License Coverage",
                value=f"{_has/_total:.0%}",
                bordered=True,
                caption=f"{_has:,} of {_total:,} GoodAI repos",
            ),
            mo.stat(
                label="OSAI Gap Map",
                value="41 subcats",
                bordered=True,
                caption="10 dimensions scored 1-5",
            ),
            mo.stat(
                label="Per-Repo Openness",
                value="Not available",
                bordered=True,
                caption="weights/data/methodology audit needed",
            ),
        ], widths="equal", gap=1),
        mo.Html(
            f'<h3 style="font-family:{F["headline"]}; font-size:1.1rem; font-weight:500; '
            f'color:{C["ink"]}; margin:20px 0 4px;">License Distribution</h3>'
            f'<p style="font-family:{F["body"]}; font-size:0.85rem; color:{C["ink_3"]}; '
            f'margin:0 0 12px;">Top 15 licenses across GoodAI repos. '
            f'<span style="color:{C["healthy"]};">Green</span> = permissive, '
            f'<span style="color:{C["warm"]};">amber</span> = copyleft/restricted.</p>'
        ),
        mo.ui.plotly(_fig, config={"displayModeBar": False}),
    ])
    return


