@app.cell(hide_code=True)
def load_absence_factor(mo, pyoso_db_conn):
    df_absence = mo.sql(
        f"""
        SELECT
          CAST(caf.amount AS INTEGER) AS absence_factor,
          COUNT(*) AS artifact_count
        FROM oso.contributor_absence_factor_to_artifact_yearly caf
        WHERE caf.metrics_sample_date >= DATE('2025-01-01')
        GROUP BY CAST(caf.amount AS INTEGER)
        ORDER BY absence_factor
        """,
        output=False,
        engine=pyoso_db_conn,
    )
    return (df_absence,)


@app.cell(hide_code=True)
def load_absence_ai_coverage(mo, pyoso_db_conn):
    df_absence_ai = mo.sql(
        f"""
        SELECT
          COUNT(DISTINCT caf.to_artifact_id) AS artifacts_with_absence,
          COUNT(DISTINCT CASE
            WHEN a.repo IS NOT NULL THEN caf.to_artifact_id
          END) AS ai_artifacts_with_absence
        FROM oso.contributor_absence_factor_to_artifact_yearly caf
        LEFT JOIN oso.artifacts_by_project_v1 abp
          ON caf.to_artifact_id = abp.artifact_id
        LEFT JOIN currentai.catalog.goodailist_repos a
          ON abp.artifact_namespace || '/' || abp.artifact_name = a.repo
        WHERE caf.metrics_sample_date >= DATE('2025-01-01')
        """,
        output=False,
        engine=pyoso_db_conn,
    )
    return (df_absence_ai,)


@app.cell(hide_code=True)
def load_funding_coverage(mo, pyoso_db_conn):
    df_funding_cov = mo.sql(
        f"""
        SELECT
          COUNT(DISTINCT f.to_artifact_id) AS funded_artifacts,
          SUM(f.amount) AS total_funding
        FROM oso.funding_received_to_artifact_over_all_time f
        WHERE f.amount > 0
        """,
        output=False,
        engine=pyoso_db_conn,
    )
    return (df_funding_cov,)


@app.cell(hide_code=True)
def tier3_stats(
    C,
    CHART_LAYOUT,
    F,
    df_absence,
    df_absence_ai,
    df_funding_cov,
    go,
    mo,
):
    _total_absence = int(df_absence_ai["artifacts_with_absence"].iloc[0])
    _ai_absence = int(df_absence_ai["ai_artifacts_with_absence"].iloc[0])
    _funded = int(df_funding_cov["funded_artifacts"].iloc[0])
    _total_funding = float(df_funding_cov["total_funding"].iloc[0])

    _single_maintainer = int(
        df_absence[df_absence["absence_factor"] == 1]["artifact_count"].sum()
    ) if len(df_absence[df_absence["absence_factor"] == 1]) > 0 else 0
    _total_measured = int(df_absence["artifact_count"].sum())

    _fig = go.Figure(go.Bar(
        x=df_absence["absence_factor"],
        y=df_absence["artifact_count"],
        marker_color=[
            C["signal"] if af == 1 else C["warm"] if af <= 2 else C["healthy"]
            for af in df_absence["absence_factor"]
        ],
        hovertemplate=(
            "Absence factor: %{x}<br>"
            "Repos: %{y:,}<extra></extra>"
        ),
    ))
    _fig.update_layout(
        **{**CHART_LAYOUT, "height": 320},
        xaxis=dict(
            title="Contributor absence factor (min people to lose 50% of commits)",
            showgrid=False, dtick=1,
        ),
        yaxis=dict(
            title="Number of repos", showgrid=True, gridcolor=C["rule"],
        ),
    )

    mo.vstack([
        mo.hstack([
            mo.stat(
                label="Absence Factor Coverage",
                value=f"{_total_absence:,}",
                bordered=True,
                caption=f"repos with bus-factor data (2025)",
            ),
            mo.stat(
                label="AI Repos Matched",
                value=f"{_ai_absence:,}",
                bordered=True,
                caption="via artifact_id join to our catalog",
            ),
            mo.stat(
                label="Funded Artifacts",
                value=f"{_funded:,}",
                bordered=True,
                caption=f"${_total_funding/1e6:,.1f}M total (OC + Gitcoin)",
            ),
            mo.stat(
                label="Single-Maintainer",
                value=f"{_single_maintainer/_total_measured:.0%}" if _total_measured > 0 else "N/A",
                bordered=True,
                caption=f"{_single_maintainer:,} of {_total_measured:,} measured repos",
            ),
        ], widths="equal", gap=1),
        mo.Html(
            f'<h3 style="font-family:{F["headline"]}; font-size:1.1rem; font-weight:500; '
            f'color:{C["ink"]}; margin:20px 0 4px;">Contributor Absence Factor Distribution</h3>'
            f'<p style="font-family:{F["body"]}; font-size:0.85rem; color:{C["ink_3"]}; '
            f'margin:0 0 12px;">How many people would need to leave before 50% of commit '
            f'activity disappears? Factor = 1 means a single point of failure.</p>'
        ),
        mo.ui.plotly(_fig, config={"displayModeBar": False}),
    ])
    return


